function Tag({children,tone="plain"}:{children:ReactNode;tone?:string}){return <span className={`tag ${tone}`}>{children}</span>}
function Status({text}:{text:string}){return <Tag tone={statusType(text)}><span className="status-dot"/>{text||"Sem status"}</Tag>}
function Avatar({name,size="normal"}:{name:string;size?:string}){return <span className={`avatar ${size}`}>{initials(name||"?")}</span>}
function Progress({value,thin=false}:{value:number;thin?:boolean}){return <div className={`progress-line ${thin?"thin":""}`}><span style={{width:`${Math.max(0,Math.min(100,value||0))}%`}}/></div>}
function Empty({icon:Icon=ClipboardCheck,title="Nenhum registro",detail="Cadastre um novo item para começar.",action}:{icon?:LucideIcon;title?:string;detail?:string;action?:ReactNode}){return <div className="empty"><div className="empty-icon"><Icon size={24}/></div><h3>{title}</h3><p>{detail}</p>{action}</div>}
function SectionTitle({title,description,action}:{title:string;description?:string;action?:ReactNode}){return <div className="section-title"><div><h3>{title}</h3>{description&&<p>{description}</p>}</div>{action}</div>}
function Metric({icon:Icon,label,value,meta,tone="blue"}:{icon:LucideIcon;label:string;value:string|number;meta:string;tone?:string}){return <div className="metric"><div className="metric-row"><span className={`metric-icon ${tone}`}><Icon size={19}/></span><ArrowUpRight size={16} className="metric-arrow"/></div><div className="metric-value">{value}</div><div className="metric-label">{label}</div><div className="metric-foot">{meta}</div></div>}
function PageHeader({eyebrow,title,description,actions}:{eyebrow?:string;title:string;description:string;actions?:ReactNode}){return <div className="page-header v4-page-header"><div className="v4-heading-copy"><div className="eyebrow"><span className="v4-live-dot"/> {eyebrow||"WMS EXPERT  /  ESTEIRA DE ENTREGAS"}</div><h1>{title}</h1><p>{description}</p><div className="v4-heading-caption"><CheckCircle2 size={13}/> Gestão operacional centralizada · dados da base em uso</div></div><div className="header-actions">{actions}</div></div>}
function RouteOverview({items}:{items:{icon:LucideIcon;label:string;value:string|number;foot:string;tone?:string}[]}){return <section className="v4-overview" aria-label="Indicadores desta área">{items.map(({icon:Icon,label,value,foot,tone="cyan"},i)=><div className={`v4-overview-tile v4-tone-${tone}`} key={`${label}-${i}`}><div className="v4-overview-top"><span className="v4-overview-icon"><Icon size={18} strokeWidth={1.9}/></span><span className="v4-overview-marker"/></div><strong className="v4-overview-value">{value}</strong><span className="v4-overview-label">{label}</span><small>{foot}</small></div>)}</section>}
function SearchField({value,onChange,placeholder="Buscar..."}:{value:string;onChange:(s:string)=>void;placeholder?:string}){return <label className="searchfield"><Search size={17}/><input value={value} onChange={e=>onChange(e.target.value)} placeholder={placeholder}/>{value&&<button aria-label="Limpar busca" onClick={()=>onChange("")}><X size={14}/></button>}</label>}
